"use strict";(globalThis.webpackChunkdocumentation||=[]).push([[658],{3179(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/VEIL/manual/intro","label":"Veil","docId":"intro","unlisted":false},{"type":"link","href":"/VEIL/manual/user-guide","label":"Browser User Guide","docId":"user-guide","unlisted":false},{"type":"link","href":"/VEIL/manual/cli","label":"Python CLI","docId":"cli","unlisted":false},{"type":"link","href":"/VEIL/manual/self-hosting","label":"Build and Self-Host","docId":"self-hosting","unlisted":false},{"type":"link","href":"/VEIL/manual/security-model","label":"Security Model and Limitations","docId":"security-model","unlisted":false}]},"docs":{"cli":{"id":"cli","title":"Python CLI","description":"The CLI is an interactive terminal application with four actions: Write, Decode, Hide Stego, and Reveal Stego. It runs locally and shares the browser app\'s payload formats.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Veil","description":"Veil combines password-based encryption with text and image steganography. Use it in the hosted browser app, run the Python CLI, or build and host it yourself.","sidebar":"tutorialSidebar"},"security-model":{"id":"security-model","title":"Security Model and Limitations","description":"Veil applies password-derived authenticated encryption before using a text or image carrier. Encryption protects the payload; chatter and pixel embedding are concealment formats, not substitutes for encryption.","sidebar":"tutorialSidebar"},"self-hosting":{"id":"self-hosting","title":"Build and Self-Host","description":"The site is static. Building it copies the canonical browser app (docs/Veil.html) and its logo into the output. In this repository, the post-build step also publishes Docusaurus to docs/manual/, creating a real documentation route alongside the landing page and browser app.","sidebar":"tutorialSidebar"},"user-guide":{"id":"user-guide","title":"Browser User Guide","description":"The hosted app and the local docs/Veil.html page have the same four tabs: Write, Decode, Image \u2192 text, and Image in image. The three creation workflows are text-to-chatter, image-to-chatter, and image-in-image; Decode and Reveal recover their outputs.","sidebar":"tutorialSidebar"}}}}')}}]);